<template><div class="page"><el-card><template #header><div style="display:flex;justify-content:space-between;align-items:center"><span>订单详情 #{{ order.order_no }}</span><el-button @click="$router.back()">返回</el-button></div></template><el-descriptions :column="2" border><el-descriptions-item label="订单号">{{ order.order_no }}</el-descriptions-item><el-descriptions-item label="订单状态"><el-tag :type="statusType">{{ statusText }}</el-tag></el-descriptions-item><el-descriptions-item label="下单时间">{{ order.created_at }}</el-descriptions-item><el-descriptions-item label="支付时间">{{ order.paid_at || '-' }}</el-descriptions-item><el-descriptions-item label="收货人">{{ order.consignee }}</el-descriptions-item><el-descriptions-item label="联系电话">{{ order.phone }}</el-descriptions-item><el-descriptions-item label="收货地址">{{ order.address }}</el-descriptions-item><el-descriptions-item label="订单备注">{{ order.remark || '-' }}</el-descriptions-item><el-descriptions-item label="商品总额">¥{{ order.goods_amount }}</el-descriptions-item><el-descriptions-item label="运费">¥{{ order.shipping_amount || 0 }}</el-descriptions-item><el-descriptions-item label="优惠金额">¥{{ order.discount_amount || 0 }}</el-descriptions-item><el-descriptions-item label="实付金额"><span style="color:#f56c6c;font-weight:bold">¥{{ order.total_amount }}</span></el-descriptions-item></el-descriptions><el-divider>商品清单</el-divider><el-table :data="order.items || []" border><el-table-column label="商品" min-width="200"><template #default="{row}"><div style="display:flex;align-items:center;gap:10px"><el-image v-if="row.image" :src="row.image" style="width:50px;height:50px" fit="cover"/><span>{{ row.goods_name }}</span></div></template></el-table-column><el-table-column prop="spec" label="规格" width="120"/><el-table-column prop="price" label="单价" width="100"/><el-table-column prop="quantity" label="数量" width="80"/><el-table-column prop="total" label="小计" width="100"/></el-table></el-card></div></template><script setup>import{ref,computed,onMounted}from'vue';import{useRoute}from'vue-router';import request from'@/utils/request';const route=useRoute();const order=ref({});const statusText=computed(()=>{const map={0:'待付款',1:'待发货',2:'待收货',3:'已完成',4:'已取消',5:'已退款'};return map[order.value.status]||'未知'});const statusType=computed(()=>{const map={0:'warning',1:'primary',2:'success',3:'success',4:'info',5:'danger'};return map[order.value.status]||'info'});onMounted(async()=>{const res=await request({url:`/merchant/orders/${route.params.id}`});order.value=res.data||{}})</script>
